pub fn append_vectors<T: Copy>(v1: &Vec<T>, v2: &Vec<T>) -> Vec<T> {
    let mut out = Vec::with_capacity(v1.len() + v2.len());
    out.extend_from_slice(v1.as_slice());
    out.extend_from_slice(v2.as_slice());
    out
}

